package org.rabochaya.projects;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.InputType;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Explicit area job for visible composition layers; onStop pauses, resume always needs a tap. */
public final class CompositionDownloadActivity extends Activity {
 private long project;private TextView status;private final EditText[] fields=new EditText[6];private Button calculate,resume;private final LinkedHashMap<String,CheckBox> choices=new LinkedHashMap<>();private final Map<String,MapComposition.Layer> offered=new HashMap<>();private CompositionDownloadSettings.Snapshot snapshot;private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean cancelled,disposed;private boolean busy;private volatile OnlineTiles active;
 protected void onCreate(Bundle saved){super.onCreate(saved);project=getIntent().getLongExtra("project",-1);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff232d1d);root.setPadding(12,8,12,8);setContentView(root);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);ScrollView scroll=new ScrollView(this);LinearLayout form=new LinearLayout(this);form.setOrientation(1);scroll.addView(form);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));text(form,"Кеш слоёв",21);status=text(form,"",14);text(form,"Только видимые онлайн-слои с ненулевой непрозрачностью. До 20 000 уникальных тайлов, до 256 МиБ на источник. Скачиваются только доступные уровни каждого источника. Локальные карты не скачиваются. Объекты и вложения не передаются.",14);
  try{text(form,"Состав: "+names(current()),14);}catch(IOException e){status.setText(e.getMessage());}
  CheckBox network=new CheckBox(this);network.setText("Разрешить загрузку тайлов из интернета");network.setTypeface(WorkspaceUi.font(this));network.setTextColor(-1);network.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffb8cfaa));network.setChecked(OnlineMapSettings.network(this));form.addView(network);network.setOnCheckedChangeListener((v,on)->{OnlineMapSettings.prefs(this).edit().putBoolean("network",on).commit();if(!on&&busy)pause();});
  double[] bounds=getIntent().getDoubleArrayExtra("bounds");if(bounds==null||bounds.length!=4)bounds=new double[]{-1,-1,1,1};int z=Math.max(0,Math.min(23,(int)getIntent().getDoubleExtra("zoom",2)));String[] values={number(bounds[0]),number(bounds[1]),number(bounds[2]),number(bounds[3]),""+z,""+z};String failure="";
  try{snapshot=CompositionDownloadSettings.load(this,project);if(snapshot.job!=null){CompositionDownloadJob j=snapshot.job;values=new String[]{number(j.west),number(j.south),number(j.east),number(j.north),""+j.min,""+j.max};status.setText("Сохранённое задание: "+j.completed+" / "+j.tasks.size()+". Продолжение проверит все тайлы; имеющиеся не скачиваются повторно.");}}catch(Exception e){failure=e.getMessage();status.setText(failure);}
  text(form,"Слои для нового задания (состав карты не изменяется)",15);
  try{MapComposition map=current();int index=0;for(MapComposition.Layer layer:map.layers)if(layer.visible&&layer.opacity>0&&("custom".equals(layer.kind)||"catalog".equals(layer.kind))){TileSource source=layer.source();CheckBox box=new CheckBox(this);box.setText((++index)+". "+layer.name);box.setTextColor(-1);box.setTypeface(WorkspaceUi.font(this));box.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffb8cfaa));boolean checked=source!=null&&source.downloads;if(snapshot!=null&&snapshot.job!=null){checked=false;for(MapComposition.Layer old:snapshot.job.composition.layers)if(old.id.equals(layer.id))checked=true;}if(saved!=null&&saved.getLong("project",-1)==project&&saved.getString("job_generation","").equals(snapshot==null||snapshot.job==null?"":snapshot.job.generation)&&saved.containsKey("selected"))checked=saved.getStringArrayList("selected").contains(layer.id);box.setChecked(checked);box.setEnabled(source!=null);form.addView(box);if(source!=null)text(form,"z"+source.minZoom+"–"+source.maxZoom+(source.downloads?"":" · только просмотр; загрузка области запрещена"),12);choices.put(layer.id,box);offered.put(layer.id,layer);}}catch(IOException e){status.setText(e.getMessage());}
  String[] labels={"Запад","Юг","Восток (запад > востока — через 180°)","Север","Минимальный zoom","Максимальный zoom"};for(int i=0;i<6;i++){text(form,labels[i],14);EditText input=new EditText(this);input.setTypeface(WorkspaceUi.font(this));input.setSingleLine(true);input.setTextColor(0xff202020);input.setBackgroundColor(-1);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED|InputType.TYPE_NUMBER_FLAG_DECIMAL);input.setText(saved!=null&&saved.getLong("project",-1)==project&&saved.getString("job_generation","").equals(snapshot==null||snapshot.job==null?"":snapshot.job.generation)?saved.getString("field_"+i,values[i]):values[i]);fields[i]=input;form.addView(input,new LinearLayout.LayoutParams(-1,-2));}
  LinearLayout actions=new LinearLayout(this);root.addView(actions);calculate=button(actions,"Рассчитать",()->calculate());resume=button(actions,"Продолжить",()->resumeJob());button(actions,"Назад / пауза",()->onBackPressed());calculate.setEnabled(failure.isEmpty());resume.setEnabled(failure.isEmpty()&&snapshot!=null&&snapshot.job!=null);
 }
 private static String names(MapComposition c){StringBuilder text=new StringBuilder();for(MapComposition.Layer l:c.layers)if(l.visible&&l.opacity>0&&l.source()!=null){if(text.length()>0)text.append(" · ");text.append(l.name);}return text.toString();}
 private static String number(double v){return String.format(Locale.US,"%.8f",v);}private TextView text(LinearLayout parent,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(-1);t.setTypeface(WorkspaceUi.font(this));parent.addView(t);return t;}
 private Button button(LinearLayout row,String name,Runnable action){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTypeface(WorkspaceUi.font(this));b.setTextSize(12);b.setPadding(4,2,4,2);b.setMinHeight(0);b.setMinimumHeight(0);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{if(!busy)action.run();else pause();});return b;}
 private MapComposition current()throws IOException{if(!MapCompositionSettings.active(this,project))throw new IOException("Сначала включите состав в «Слои карты»");return MapCompositionSettings.load(this,project).composition;}
 private void calculate(){try{double[] v=new double[4];for(int i=0;i<4;i++)v[i]=Double.parseDouble(fields[i].getText().toString().trim().replace(',','.'));List<MapComposition.Layer> selected=new ArrayList<>();for(Map.Entry<String,CheckBox> item:choices.entrySet())if(item.getValue().isChecked())selected.add(offered.get(item.getKey()));CompositionDownloadJob job=new CompositionDownloadJob(new MapComposition(project,selected),v[0],v[1],v[2],v[3],Integer.parseInt(fields[4].getText().toString().trim()),Integer.parseInt(fields[5].getText().toString().trim()));AlertDialog dialog=new AlertDialog.Builder(this).setMessage("Загрузить область для "+job.tasks.size()+" уникальных тайлов: "+names(job.composition)+"? "+(snapshot.job==null?"":"Прежнее задание будет заменено, полученный кеш сохранён. ")+"Скачивание идёт, пока открыт экран; после остановки продолжение только явно.").setPositiveButton("Скачать",(d,w)->start(job)).setNegativeButton("Отмена",null).create();dialog.setOnShowListener(d->font(dialog.getWindow().getDecorView()));dialog.show();}catch(Exception e){status.setText("Не рассчитано: "+e.getMessage());}}
 private void font(View v){if(v instanceof TextView)((TextView)v).setTypeface(WorkspaceUi.font(this));if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)font(((ViewGroup)v).getChildAt(i));}
 private void resumeJob(){try{CompositionDownloadSettings.Snapshot latest=CompositionDownloadSettings.load(this,project);if(snapshot==null||snapshot.job==null||latest.job==null||!snapshot.job.generation.equals(latest.job.generation))throw new IOException("Сохранённое задание заменено; откройте экран заново");snapshot=latest;start(latest.job);}catch(IOException e){status.setText("Не запущено: "+e.getMessage());}}
 private void start(CompositionDownloadJob job){try{if(!OnlineMapSettings.network(this))throw new IOException("Разрешите загрузку тайлов из интернета");if(!job.matches(current()))throw new IOException("Выбранные слои изменены; откройте экран заново");snapshot=CompositionDownloadSettings.begin(this,project,snapshot,job.progress(0));busy=true;cancelled=false;calculate.setEnabled(false);resume.setEnabled(false);status.setText("Проверка полученных тайлов…");final CompositionDownloadSettings.Snapshot started=snapshot;worker.execute(()->download(started));}catch(Exception e){status.setText("Не запущено: "+e.getMessage());}}
 private void download(CompositionDownloadSettings.Snapshot initial){CompositionDownloadSettings.Snapshot progress=initial;Map<String,OnlineTiles> readers=new HashMap<>();int done=0;String result;try{for(CompositionDownloadJob.Task task:initial.job.tasks){if(!OnlineMapSettings.network(this))cancelled=true;if(cancelled||disposed)break;String key=task.source.id+":"+task.source.minZoom+":"+task.source.maxZoom;OnlineTiles cache=readers.get(key);if(cache==null){cache=new OnlineTiles(this,task.source);readers.put(key,cache);}active=cache;if(cancelled||disposed||!OnlineMapSettings.network(this)){cancelled=true;cache.cancel();break;}boolean saved=cache.contains(task.z,task.x,task.y);if(cancelled||disposed){cache.cancel();break;}cache.download(task.z,task.x,task.y);done++;if(done%5==0||done==initial.job.tasks.size()){progress=CompositionDownloadSettings.progress(this,project,progress,done);final int completed=done;runOnUiThread(()->{if(!disposed)status.setText("Проверено / сохранено: "+completed+" / "+initial.job.tasks.size());});}if(!saved)Thread.sleep(200);}if(done!=progress.job.completed)progress=CompositionDownloadSettings.progress(this,project,progress,done);result=(cancelled||disposed?"Пауза. ":"Готово. ")+done+" / "+initial.job.tasks.size()+"; кеш сохранён.";}catch(Exception e){String stateError="";try{if(done!=progress.job.completed)progress=CompositionDownloadSettings.progress(this,project,progress,done);}catch(IOException state){stateError=" Прогресс записать не удалось; продолжение проверит кеш заново.";}result=(cancelled||disposed?"Пауза. "+done+" / "+initial.job.tasks.size()+"; кеш сохранён.":"Остановлено: "+e.getMessage()+". Полученный кеш сохранён; продолжите явно.")+stateError;}finally{active=null;try{for(OnlineTiles cache:readers.values())cache.close();}finally{CompositionDownloadSettings.end(project,initial.job.generation);}}final String message=result;runOnUiThread(()->{busy=false;if(!disposed){try{snapshot=CompositionDownloadSettings.load(this,project);}catch(IOException e){status.setText(e.getMessage());return;}status.setText(message);calculate.setEnabled(true);resume.setEnabled(snapshot.job!=null);}});}
 private void pause(){cancelled=true;OnlineTiles cache=active;if(cache!=null)cache.cancel();status.setText("Пауза… Полученный кеш сохраняется");}public void onBackPressed(){if(busy)pause();else super.onBackPressed();}
 protected void onSaveInstanceState(Bundle b){b.putLong("project",project);b.putString("job_generation",snapshot==null||snapshot.job==null?"":snapshot.job.generation);ArrayList<String> selected=new ArrayList<>();for(Map.Entry<String,CheckBox> item:choices.entrySet())if(item.getValue().isChecked())selected.add(item.getKey());b.putStringArrayList("selected",selected);for(int i=0;i<6;i++)b.putString("field_"+i,fields[i].getText().toString());super.onSaveInstanceState(b);}protected void onStop(){if(busy)pause();super.onStop();}protected void onDestroy(){disposed=true;cancelled=true;worker.shutdown();super.onDestroy();}
}
